import pathlib,json,hashlib
root=pathlib.Path.cwd();p=root/'data/processed/evaluation.json';data=json.loads(p.read_text(encoding='utf-8'));rows=[r for r in data['evidence'] if r['model']=='naive' and r['horizon']==1 and r['target'].startswith('2023')];out={'source':'data/processed/evaluation.json','source_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'scope':'Every saved one-week persistence actual-versus-predicted evaluation row with target in 2023, both absent-day scenarios. No synthetic points.','rows':rows};(root/'public/api/v2/dashboard.json').write_text(json.dumps(out,separators=(',',':'))+'\n',encoding='utf-8');print(json.dumps({'backtest_rows':len(rows)}))
